WITH scored AS (SELECT id, store_id, LEAD(quantity) OVER w_hist AS next_quantity, LAG(quantity) OVER w_hist AS prev_quantity, ROW_NUMBER() OVER w_hist AS seq_no, SUM(quantity) OVER w_part AS cumulative_quantity FROM inventory WINDOW w_hist AS (PARTITION BY store_id ORDER BY last_restock, id), w_part AS (PARTITION BY store_id, product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), scored_inventory AS (SELECT id, next_quantity, prev_quantity, cumulative_quantity, AVG(seq_no) OVER (PARTITION BY store_id ORDER BY cumulative_quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS seq_no_avg_2, LAST_VALUE(next_quantity) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY cumulative_quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_next_quantity, LEAD(next_quantity, 1) OVER (ORDER BY seq_no, id) AS next_next_quantity FROM scored WHERE store_id IN (1, 5, 6)), remaining_keys AS (SELECT id FROM scored_inventory EXCEPT SELECT id FROM inventory WHERE product_id IN (5, 7, 10)), reconciled AS (SELECT s.* FROM scored_inventory s INNER JOIN remaining_keys k ON s.id = k.id), with_windows AS (SELECT *, CUME_DIST() OVER (ORDER BY seq_no_avg_2 DESC NULLS FIRST) AS seq_no_avg_2_cume_dist, RANK() OVER (ORDER BY next_quantity DESC NULLS FIRST) AS next_quantity_rank FROM reconciled), valid AS (SELECT *, cumulative_quantity - seq_no_avg_2_cume_dist AS cumulative_quantity_minus_seq_no_avg_2_cume_dist, next_next_quantity + next_quantity_rank AS next_next_quantity_plus_next_quantity_rank FROM with_windows WHERE next_quantity != 110), totals AS (SELECT CASE WHEN cumulative_quantity_minus_seq_no_avg_2_cume_dist >= 69 THEN 'LARGE' ELSE 'SMALL' END AS cumulative_quantity_minus_seq_no_avg_2_cume_dist_tier, CASE WHEN next_quantity >= 214 THEN 'LARGE' ELSE 'SMALL' END AS next_quantity_tier, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS num_rows, ROUND(AVG(seq_no_avg_2_cume_dist), 2) AS avg_seq_no_avg_2_cume_dist FROM valid GROUP BY CUBE (CASE WHEN cumulative_quantity_minus_seq_no_avg_2_cume_dist >= 69 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN next_quantity >= 214 THEN 'LARGE' ELSE 'SMALL' END) HAVING avg_seq_no_avg_2_cume_dist > 0) SELECT next_quantity_tier, num_rows, avg_seq_no_avg_2_cume_dist FROM totals;
